-- lambe-rex shim. Installed by `lambe setup rex`; load it from init.lua.
-- All logic lives in the lambe/ directory beside this file and your
-- settings in lambe.config.lua. Do not edit this file: it is managed.

local DIR = "@LAMBE_DIR@" -- filled in by `lambe setup rex`

package.path = DIR .. "/?.lua;" .. package.path
for name in pairs(package.loaded) do
  if name:sub(1, 6) == "lambe." then package.loaded[name] = nil end
end

local function settings()
  local ok, cfg = pcall(dofile, DIR .. "/lambe.config.lua")
  if ok and type(cfg) == "table" then return cfg end
  return {} -- absent or broken: defaults, and `lambe_check` explains
end

local ok, lambe = pcall(require, "lambe.init")
if ok then
  return lambe.setup(settings())
end
-- A broken install must not break the rest of the Rex config: keep one
-- action that says what is wrong.
local problem = "Lambe is not installed correctly (" .. tostring(lambe) .. "); run `lambe setup rex --apply`"
rex.log("error", problem)
rex.action{
  name = "lambe_check",
  title = "Lambe: Check Setup",
  category = "Lambe",
  description = "Explain why the Lambe actions are unavailable",
  run = function() error(problem, 0) end,
}
